/**
 * Strip control characters and bound any free text that came back from a probe.
 *
 * NOTE the character class includes \n (0x0a) and \t (0x09). That is correct for
 * single-value text — a hostname, a container id — but it makes this function
 * WRONG for anything you intend to parse line-by-line or column-by-column. Use
 * `cleanLines` for that; see the incident note there.
 */
function clean(s: unknown, max: number): string {
  // eslint-disable-next-line no-control-regex
  return String(s ?? "").replace(/[\x00-\x1f\x7f]/g, "").trim().slice(0, max);
}

/**
 * Same sanitisation as `clean`, but PRESERVES newlines and tabs so the result can
 * still be split into lines or columns.
 *
 * WHY THIS EXISTS (found by the 2026-07-26 migration rehearsal, the first time the
 * engine was ever run end-to-end against a purpose-built messy source):
 *
 * Six verification paths called `clean()` and then `.split("\n")` on the result.
 * Because `clean` deletes newlines, every one of those splits returned a SINGLE
 * element containing the whole output concatenated — so the parse silently
 * produced nothing while the surrounding code reported success. Confirmed
 * consequences, all in code written to catch real incidents:
 *
 *   - `resolvesHere()` could never match: every A record collapsed into one
 *     string, so `.includes(ip)` was always false. A domain that HAD been pointed
 *     at the new server was reported as not pointing there, which blocks HTTP-01
 *     issuance — the certificate step can never succeed.
 *   - the systemd health gate read `activeSubState/running` as one corrupted
 *     token and called a healthy unit "NOT running"; `NRestarts` parsed to NaN,
 *     so field note 26's crash-loop detector could never fire.
 *   - the database-account check reported "none of the 3 accounts could be
 *     recreated" when all three had landed with hashes and grants intact.
 *   - the stale-IP/cert sweep parsed ZERO lines and reported success.
 *
 * The codebase had already documented this exact hazard for `probeBody` and then
 * applied the lesson nowhere else. If you add a parser, ask which of these two
 * functions you want — `nft -c`-style syntax checks will not tell you.
 */
function cleanLines(s: unknown, max: number): string {
  // Keep \n and \t; strip every other control character.
  // eslint-disable-next-line no-control-regex
  return String(s ?? "").replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, "").trim().slice(0, max);
}

/** A Docker image reference we are willing to put in a command at all. */
function validImageRef(r: string): boolean {
  return (
    typeof r === "string" &&
    IMAGEREF_RE.test(r) &&
    !r.includes("..") &&
    !r.includes("//") &&
    !r.startsWith("-") &&
    !r.includes("<none>")
  );
}

