/** True when a live certificate + key really exist here for this exact name. */
async function certExists(conn: Client, domain: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain)) return false;
  return shOk(conn, `test -s /etc/letsencrypt/live/${domain}/fullchain.pem && test -s /etc/letsencrypt/live/${domain}/privkey.pem`);
}

/** Does this hostname already resolve to the NEW server? HTTP-01 requires it. */
async function resolvesHere(conn: Client, domain: string, ip: string): Promise<boolean> {
  if (!DOMAIN_RE.test(domain) || !IPV4_RE.test(ip)) return false;
  const r = await sh(conn, `getent ahostsv4 ${domain} 2>/dev/null | awk '{print $1}' | sort -u | head -n 8`);
  // cleanLines, NOT clean: `clean` strips the newlines this output is split on, so
  // every A record collapsed into one string and `.includes(ip)` was ALWAYS false.
  // A domain correctly pointed at the new server was reported as not pointing
  // there, which blocks HTTP-01 and makes certificate issuance unreachable.
  return cleanLines(r.stdout, 512).split("\n").map((s) => s.trim()).includes(ip);
}

