/**
 * The major version out of a `--version` line, or "" when there isn't one.
 *
 * Handles the shapes real programs actually print: `v20.11.1` (node),
 * `Python 3.11.2`, `ruby 3.1.4p223`, `PHP 8.2.7 (cli)`, `go version go1.21.5`.
 * Deliberately returns "" rather than a guess — an unknown version must not be
 * compared, because a false mismatch is as misleading as a missed one.
 */
export function majorVersion(s: string): string {
  const m = /(?:^|[^\d.])v?(\d{1,4})\.\d/.exec(String(s ?? ""));
  return m ? m[1] : "";
}

