   * Every hostname the SOURCE server answered on, from its own live vhost
   * config. THE DENOMINATOR. Empty means the source inventory could not be read
   * — we then have no honest denominator and say so rather than scoring
   * ourselves against our own homework.
   */
  sourceDomains: string[];
  /** The names actually probed (the probe budget caps this below sourceDomains). */
  probeNames: string[];
  /** Per-domain probe verdicts. Only `serving: true` counts towards the score. */
  siteProbes: { domain: string; serving: boolean }[];
  /** Units the exec pre-flight / health gate refused to certify as running. */
  unitBlockers: { domain: string }[];
  /**
   * Steps that recorded `status: "failed"`. These used to have NO effect on the
   * outcome: a run could fail to restore a database, fail to pull an image and
   * fail to start a container, and still be scored COMPLETED because those
   * failures were not domains and were not units. A failure the customer can read
   * in the step list must also be a failure in the verdict.
   */
  failedSteps?: { step: string }[];
  /**
   * Containers the source reported (`docker ps -aq | wc -l`) that we could not
   * read a usable shape for. Silent container loss cannot be scored as success.
   */
  unreadContainers?: number;
};

