/**
 * The configured tax/VAT rate as a percent number (reads the `tax_percent` Setting).
 *
 * ⚠ THIS RATE IS NOT CHARGED TO ANYONE. `applyTaxFromSettings` has exactly one call site
 * — the MRR reference figure on /admin/products — and no charge path passes `taxCents` to
 * `invoiceCreateData`, so every `Invoice` row in the system stores `taxCents: 0` and every
 * rendered invoice shows Tax $0.00. QA P1-11 / DOCUMENTATION.md gap 22.
 *
 * Deliberately left that way. Starting to collect tax is a legal and business decision
 * (registration, rate by jurisdiction, reverse charge, invoice content requirements, and
 * remittance) and silently switching it on because a settings field existed would be a
 * far more serious error than the field being inert. What was fixed instead is the lie:
 * Settings → Billing now states on the control itself that the rate is display-only and
 * must not be relied on to collect VAT/GST.
 *
 * If tax is ever genuinely charged, the wiring is `applyTax()` at each charge site plus
 * `taxCents` into `invoiceCreateData` — and the note in
 * components/admin/settings/BillingPanel.tsx must be deleted in the same commit.
 */
export async function taxRate(): Promise<number> {
  const n = Number(await getSetting("tax_percent"));
  return Number.isFinite(n) && n > 0 ? n : 0;
}


